function Legal(kind, back) {
  currentScreen = () => Legal(kind, back); Clear('legal'); SetArt('Art/home-paddock', false); Shade('dim heavy');
  const shop = L.shopProducts();
  const notices = shop.notices;
  const c = L.consentVersions;
  const docs = {
    terms: ['利用規約', `版：${c.termsVersion}\n\n本文は運営が用意します（このプロトタイプでは見出しのみ）。\n同意の版と時刻はサーバーに記録され、版が上がると再同意を求めます（REQ-UXS-001）。`],
    privacy: ['プライバシーポリシー', `版：${c.privacyVersion}\n\n本文は運営が用意します（このプロトタイプでは見出しのみ）。`],
    tokushoho: [notices['legal.tokushoho'], '販売事業者・所在地・連絡先・販売価格・支払時期・引渡時期・返品について（本文は運営が用意します）。\n\n' + [notices['shop.no_auto_renew'], notices['shop.pass_season_only'], notices['shop.allowance_daily_claim']].join('\n')],
    shikin: [notices['legal.shikin_kessai'], '前払式支払手段（有償コイン）の発行者・支払可能金額・有効期間・問い合わせ先（本文は運営が用意します）。\n\n' + notices['shop.paid_first']],
    paidFirst: ['有償コインの使用順', notices['shop.paid_first'] + '\n\n有償コインと無償コインは分けて表示します。「有償限定」の品は有償コインだけで買えます。'],
  };
  const [title, body] = docs[kind];
  const d = Dialog('Legal', 1000, 700);
  Kicker('法定表示・規約', 52, 48, d);
  Txt(title, 52, 112, 896, isJa() ? 34 : 27, WHITE, d, { nowrap: !isJa() }); // English titles are longer: one line
  Hair(52, 178, 896, d);
  // REQ-L10N-008: the notices required by Japanese law (特商法・資金決済法) stay in Japanese; in English a courtesy
  // translation follows that claims no legal effect outside Japan
  const legalJa = !isJa() && (kind === 'tokushoho' || kind === 'shikin');
  const bodyEl = Txt(body, 52, 206, 896, legalJa ? 16 : 19, MUTED, d, { lh: legalJa ? 1.6 : 1.75 });
  if (legalJa) {
    bodyEl.classList.add('keep-ja'); bodyEl.lang = 'ja';
    const note = Txt(EN_LEGAL_NOTE + '\n\n' + (L.l10n.translate(body) ?? ''), 52, 206 + 16 * 1.6 * (body.split('\n').length + 1.4), 896, 15, SOFT, d, { lh: 1.5 });
    note.dataset.courtesy = 'en';
  }
  Cta('閉じる', 52, 590, 380, back, d);
  EnToggle();
}

