/** ③ today's to-do (login bonus, daily missions, first-win bonus) in a drawer. */
function Missions(ms, fw, bonus) {
  Sheet('ミッション', '今日やること', (s, close, y) => {
    const lb = player.loginBonus;
    const row = (yy, title, value, sub, frac, doneFlag) => {
      Txt((doneFlag ? '✓ ' : '') + title, 48, yy, 380, 21, doneFlag ? OK : WHITE, s, { weight: 500 });
      Txt(value, 400, yy, 212, 21, GOLD, s, { weight: 700, align: 'right', cls: 'num' });
      if (frac != null) Gauge(48, yy + 38, 564, frac, s, { gold: doneFlag });
      Txt(sub, 48, yy + (frac != null ? 56 : 38), 564, 14, SOFT, s);
      Hair(48, yy + 92, 564, s);
    };
    row(y, 'ログインボーナス', lb?.beginnerDay ? `初心者 ${lb.beginnerDay}/7日` : `${lb?.streakDay ?? 0}日目`, bonus ? '受け取りました：' + rewardText(bonus.reward) : '今日の分は受け取り済み', null, true);
    ms.forEach((m, i) => row(y + 112 + i * 112, 'デイリー：' + missionName(m), `${m.progress} / ${m.target}${m.claimed ? '　受取済' : ''}`, m.claimed ? '受け取り済み' : m.progress >= m.target ? '受け取れます' : m.kind === 'training' ? '調教で進みます' : 'レースで進みます', m.progress / m.target, m.progress >= m.target));
    const yy = y + 112 + ms.length * 112;
    row(yy, '初勝利ボーナス', fw.remaining > 0 ? `残り${fw.remaining}回` : '本日終了', fw.next ? `今日の次の1着で 無償コイン+${fw.next}（ランク戦）` : '明日また受け取れます', null, fw.remaining === 0);
    const claimable = ms.filter((x) => x.progress >= x.target && !x.claimed);
    if (claimable.length) Cta('受け取る', 48, 790, 360, async () => { for (const x of claimable) await L.claimMission(x.id); toast('ミッション報酬を受け取りました'); Home(); }, s);
  });
}
