// ---- purchase confirmation: unregistered / registered / under 18 / over the limit (REQ-PUR-001/002, 06 §6.8) — 18
let ageForm = null; // { year, month, guardian }
async function PurchaseConfirm(productId, back) {
  if (back) purchaseReturn = back;
  currentScreen = () => PurchaseConfirm(productId);
  const shop = L.shopProducts();
  const p = shop.products.find((x) => x.id === productId);
  const r = await L.purchaseIntent(productId);
  Clear('purchase'); SetArt('Art/home-paddock', false); Shade('dim');
  const box = Dialog('Purchase', 1100, 760, { y: 70, a: .95 });
  el('rule', 48, 30, 84, 3, box);
  Txt('購入の確認', 48, 44, 600, 24, WHITE, box, { weight: 700, ls: '.05em' });
  Txt('決済の前に、商品と条件を確認します。', 48, 76, 600, 14, MUTED, box);
  Txt('選択アイテム', 48, 124, 300, 16, MUTED, box, { weight: 500 });
  Txt(p.name, 48, 150, 700, 34, WHITE, box);
  Txt(yen(p.priceYen) + '（税込）', 760, 156, 292, 30, GOLD, box, { align: 'right', cls: 'num' });
  Txt(contentsText(p), 48, 208, 1004, 17, WHITE, box, { weight: 500, lh: 1.55 });
  const notices = p.noticeKeys.filter((k) => !k.startsWith('legal.')).map((k) => shop.notices[k]).filter(Boolean);
  Txt(notices.join('\n'), 48, 248, 1004, 13, SOFT, box, { lh: 1.6 });
  Hair(48, 330, 1004, box);
  const state = el('pstate', 48, 352, 1004, 270, box);
  const S = (t, y, size, c, o = {}) => Txt(t, 0, y, 1004, size, c, state, o);
  const close = () => { ageForm = null; (purchaseReturn ?? Home)(); };
  if (r.ok) {
    // registered: what is bought, the free coins on top (first time only), this month's remaining limit
    const v = r.value;
    state.dataset.state = 'registered';
    Kicker('年齢確認済み', 0, 0, state, { rule: false, size: 16, color: OK });
    S(v.firstPurchaseBonus ? v.firstPurchaseBonus.label : 'はじめての購入ボーナスの対象ではありません', 34, 19, v.firstPurchaseBonus ? CYAN : DIM, { weight: 500 });
    S(v.monthlyLimitYen == null ? '今月の購入上限：なし（20歳以上）' : `今月の購入上限 ${yen(v.monthlyLimitYen)}　·　あと ${yen(v.remainingYen)}　（翌月1日に戻ります）`, 72, 19, WHITE, { weight: 500 });
    if (v.pass) S(`有効期間：${seasonEnd(v.pass.endsAt)}まで（今シーズン限り・自動更新なし）${v.pass.remainingDays != null ? '　残り' + v.pass.remainingDays + '日' : ''}`, 110, 16, GOLD);
    if (v.allowance) S(`${v.allowance.days}日間、毎日 無償コイン${v.allowance.dailyFreeCoins}枚（自動更新なし）`, 110, 16, GOLD);
    const buy = disable(Cta('購入する（プロトタイプでは決済しません）', 492, 652, 560, () => {}, box, 'gold'));
    TextLink('年齢を訂正する', 0, 160, 200, () => { buy.remove(); ageForm = { year: '', month: '', guardian: false, correcting: true }; AgeForm(productId, box, state); }, state);
  } else if (r.code === 'AGE_REQUIRED' || r.code === 'GUARDIAN_CONSENT_REQUIRED') {
    state.dataset.state = r.code === 'AGE_REQUIRED' ? 'unregistered' : 'guardian';
    if (r.code === 'GUARDIAN_CONSENT_REQUIRED') ageForm = { ...(ageForm ?? { year: '', month: '' }), guardian: false, needGuardian: true };
    AgeForm(productId, box, state);
  } else if (r.code === 'AGE_LIMIT_EXCEEDED') {
    state.dataset.state = 'limit';
    const cheap = await L.purchaseIntent('coin_160');
    const rem = cheap.ok ? cheap.value.remainingYen : 0;
    S('今月の購入上限を超えます', 0, 28, WARN, { weight: 700 });
    S(`今月はあと ${yen(rem ?? 0)} まで購入できます。上限は翌月1日に戻ります。`, 50, 20, WHITE, { weight: 500 });
    S('年齢ごとの月の上限は、未成年の保護のために設けています。', 90, 15, SOFT);
    TextLink('年齢を訂正する', 0, 160, 200, () => { ageForm = { year: '', month: '', guardian: false, correcting: true }; AgeForm(productId, box, state); }, state);
  } else if (r.code === 'DELETION_PENDING') {
    state.dataset.state = 'deletion';
    S('アカウント削除の手続き中のため、購入できません', 0, 26, WARN, { weight: 700 });
    S('「その他」から削除を取り消すと購入できます。', 50, 19, WHITE, { weight: 500 });
  } else {
    state.dataset.state = 'error';
    S(r.code === 'ALREADY_PURCHASED' ? '購入済みです（1回限りの商品・今シーズンのパス）' : r.code === 'NOT_ELIGIBLE' ? 'まだ購入できません（昇級すると購入できます）' : r.message, 0, 24, GOLD, { weight: 700 });
  }
  Ghost('閉じる', 48, 658, 220, 60, close, box, 'quiet');
}
/** Birth year and month, asked only while unregistered (or to correct it); guardian consent only under 18. */
function AgeForm(productId, box, state) {
  state.innerHTML = '';
  const f = ageForm ??= { year: '', month: '', guardian: false };
  const now = new Date(L.now());
  Kicker(f.correcting ? '生年月を訂正（若い方への訂正のみ）' : '年齢区分　/　初回の購入時に1回だけ', 0, 0, state, { rule: false, size: 16 });
  Txt('生まれた年と月を選んでください', 0, 30, 600, 16, MUTED, state);
  const sel = (opts, val, x, w, onChange, label) => {
    const s = document.createElement('select'); s.className = 'el select'; s.setAttribute('aria-label', label);
    Object.assign(s.style, { left: x + 'px', top: '66px', width: w + 'px', height: '64px' });
    s.innerHTML = `<option value="">${label}</option>` + opts.map((o) => `<option value="${o}"${String(o) === String(val) ? ' selected' : ''}>${o}</option>`).join('');
    s.addEventListener('change', () => { onChange(s.value); AgeForm(productId, box, state); });
    state.appendChild(s); return s;
  };
  const years = Array.from({ length: 90 }, (_, i) => now.getFullYear() - i);
  sel(years, f.year, 0, 230, (v) => { f.year = v; }, '年');
  sel(Array.from({ length: 12 }, (_, i) => i + 1), f.month, 246, 150, (v) => { f.month = v; }, '月');
  const age = f.year && f.month ? now.getFullYear() - Number(f.year) - ((now.getMonth() + 1) < Number(f.month) ? 1 : 0) : null;
  if (age != null) Txt(`${age}歳`, 420, 78, 200, 26, WHITE, state, { weight: 700 });
  const under18 = age != null && age < L.master.ageLimits.guardianConsentUnderAge;
  if (under18 || f.needGuardian) {
    const g = Btn('保護者の同意を得ました', 0, 152, 480, 60, () => { f.guardian = !f.guardian; AgeForm(productId, box, state); }, 'check', state, (f.guardian ? '☑　' : '☐　') + '保護者の同意を得ました');
    if (f.guardian) g.classList.add('on');
    Txt('18歳未満の方は、保護者の同意が必要です。', 0, 222, 560, 15, SOFT, state);
  }
  const ok = age != null && (!under18 || f.guardian);
  const b = Cta('登録して確認する', 564, 146, 440, async () => {
    const r = await L.setAge(Number(f.year), Number(f.month), !!f.guardian);
    if (!r.ok) { toast(r.code === 'CONFLICT' ? '年齢は若い方へだけ訂正できます。サポートへ連絡してください。' : r.message); return; }
    ageForm = null; PurchaseConfirm(productId);
  }, state);
  if (!ok) disable(b);
}
