// ---- account-link prompt (REQ-UXS-073): AccountLinkPrompt on the PlayerPrefs keys muchi.link.*
const LINK_KEYS = ['muchi.link.prompt', 'muchi.link.firstPurchase'];
function linkOp(op, args = {}) {
  const store = {};
  for (const k of LINK_KEYS) { const v = prefs.get(k, null); if (v != null) store[k] = v; }
  const r = JSON.parse(engine.LinkPrompt(op, JSON.stringify(store), JSON.stringify(args)));
  for (const k of LINK_KEYS) if (r.store[k] != null) prefs.set(k, r.store[k]);
  return r;
}
const linkedProvider = () => prefs.get('muchi.link.provider', '');
function linkArgs(context) {
  return {
    context, anonymous: !linkedProvider(), day: player.unlocks.day, online: true, deletion: player.deletion?.status === 'scheduled',
    partner: !!player.flags?.partnerHorseId, gacha: !!player.flags?.tutorialGachaUsed, rankedRaces: player.rating.rankedRaces,
  };
}
/** Home / after a result / after a purchase: shows the prompt when the rules say so; returns true when it did. */
function MaybeLinkPrompt(context, next) {
  const r = linkOp('eval', linkArgs(context));
  if (!r.show) return false;
  LinkPrompt(r.trigger, next);
  return true;
}
function LinkPrompt(trigger, next = Home) {
  const v = linkOp('show', { trigger, ios: true }).view; // counts as shown now (once only)
  currentScreen = next; Clear('link-prompt'); SetArt('Art/home-paddock', false); Shade('dim');
  const box = Dialog('Link prompt', 940, 600); box.dataset.trigger = trigger;
  Kicker(trigger === 'FirstPurchase' ? 'はじめての購入の後に' : '3日目のお知らせ', 52, 48, box);
  Txt(v.title, 52, 112, 836, 32, WHITE, box, { lh: 1.4 });
  Txt(v.body, 52, 220, 836, 18, MUTED, box, { lh: 1.7 });
  v.providers.forEach((p, i) => {
    const label = p === 'apple' ? v.apple : v.google;
    const b = i === 0 ? Cta(label, 52, 376, 420, () => Link(p, next), box) : Ghost(label, 500, 382, 360, 60, () => Link(p, next), box);
    b.classList.add('provider-' + p);
  });
  TextLink(v.later, 52, 488, 160, () => { linkOp('dismiss'); next(); }, box);
  Txt(v.footnote + '（プロトタイプ：サインインの画面は省略します）', 52, 540, 836, 13, SOFT, box);
}
function Link(provider, next) {
  const r = linkOp('linked', { provider, at: L.now() });
  prefs.set('muchi.link.provider', provider);
  toast(`${provider === 'apple' ? 'Apple' : 'Google'}で引き継ぎ登録しました` + (r.event ? `（KPI ${r.event.name}）` : ''));
  globalThis.__muchi && (globalThis.__muchi.lastKpi = r.event?.name ?? null);
  (next ?? Home)();
}

// ---- rewarded ads (REQ-AD-*, contracts/protocol.md §21): the opt-in offer card, the simulated ad, the watched state.
// Server rules from the real domain (eligibility, game-day caps, sessions); the reward comes only from the simulated
// network's signed SSV callback (verified by the real verifyAdMobCallback). Never in the tutorial, a race or a result
// after 4th or worse; never interstitial — a view only starts from the card's button (RewardedAdModel's rules).
// On home the card lives in the single home card slot (HomeCard: what's new > comeback campaign > ad offer).
const AD_SECONDS = () => Math.max(1, Math.round(5 / (Number(new URLSearchParams(location.search).get('speed')) || 1)));
/** Draws the offer card for `surface` into `parent` (or nothing when the server offers none). Returns the card element. */
async function AdOfferSlot(surface, x, y, w, h, back, parent) {
  const v = await L.ads();
  const p = v.eligible ? v.placements.find((q) => q.surface === surface) : null;
  if (!p || (surface === 'home' && cur?.dataset.screen !== 'home')) return null;
  const card = Glass('Ad offer', x, y, w, h, parent, .84);
  card.classList.add('ad-card');
  card.dataset.homeCard = 'ad'; card.dataset.placement = p.id; card.dataset.state = p.left > 0 ? 'offer' : 'done';
  Kicker('動画で受け取る', 28, 24, card, { size: 16, color: p.left > 0 ? CYAN : SOFT });
  Txt(p.left > 0 ? p.rewardLabel : '今日の分は受け取りました', 28, 84, w - 56, p.left > 0 ? 24 : 19, p.left > 0 ? WHITE : MUTED, card, { weight: 700, nowrap: true });
  Txt(p.left > 0 ? `今日あと${p.left}回　·　自分で選んだ時だけ再生します` : 'また明日どうぞ（4:00 にリセット）', 28, 120, w - 56, 14, MUTED, card);
  if (p.left > 0) Cta('動画を見る', 28, h - 72, Math.min(260, w - 56), () => AdPlayer(p, back), card, 'small ad-cta');
  globalThis.__muchi && (globalThis.__muchi.lastKpi = p.left > 0 ? 'ad_offer_view' : globalThis.__muchi.lastKpi);
  return card;
}
/** The simulated rewarded ad (stands in for the native AdMob full-screen ad), then the server's verdict. */
async function AdPlayer(p, back = Home) {
  const st = await L.adStart(p.id);
  if (!st.ok) { toast(st.code === 'AD_LIMIT_REACHED' ? '今日の分は受け取りました。また明日どうぞ。' : '今は動画を用意できません。時間をおいてお試しください。'); back(); return; }
  const s = st.value;
  currentScreen = back; Clear('ad-player'); SetArt('Art/home-paddock', false); Shade('dim heavy');
  const box = Dialog('Ad player', 880, 520);
  box.classList.add('ad-player');
  Kicker('広告　/　プロトタイプのシミュレーション', 52, 44, box, { size: 15, color: SOFT });
  Txt('ここに広告の動画が流れます', 52, 170, 776, 32, WHITE, box, { align: 'center' });
  const left = Txt('', 52, 236, 776, 22, CYAN, box, { weight: 700, align: 'center', cls: 'num' });
  left.dataset.adCountdown = '1';
  Txt(`最後まで見ると「${s.rewardLabel}」を受け取れます`, 52, 290, 776, 16, MUTED, box, { align: 'center' });
  let n = AD_SECONDS(), done = false;
  Ghost('閉じる', 648, 428, 180, 56, () => { done = true; AdWatched(p, { status: 'not_completed' }, back); }, box, 'quiet small').classList.add('ad-close');
  every(1000, async () => {
    if (done) return;
    left.textContent = n > 0 ? `残り ${n} 秒` : '確認しています…';
    if (n-- > 0) return;
    done = true;
    // the network's SSV callback → the server's verdict; the client only polls the session
    const cb = await L.simulateAdCallback(s);
    const sess = await L.adSession(s.sessionId);
    AdWatched(p, sess.ok ? sess.value : { status: 'pending' }, back, cb.ok ? cb.value : null);
  });
}
/** The watched state: what the server granted (or why nothing). */
async function AdWatched(p, sess, back = Home) {
  await refresh();
  Clear('ad-watched'); SetArt('Art/home-paddock', false); Shade('dim');
  const ok = sess.status === 'rewarded';
  const box = Dialog('Ad watched', 760, 440);
  box.classList.add('ad-card'); box.dataset.state = sess.status;
  Kicker(ok ? '受け取りました' : '受け取れませんでした', 52, 44, box, { size: 16, color: ok ? CYAN : SOFT });
  Txt(ok ? sess.rewardLabel : sess.status === 'not_completed' ? '最後まで見ると受け取れます' : '今回は受け取れませんでした', 52, 116, 656, ok ? 46 : 30, ok ? GOLD : WHITE, box, { weight: 700 });
  Txt(ok ? `無償コインの所持：${fmt(sess.wallet.free)}枚（有償コインとは別に管理しています）` : '動画は自分で選んだ時だけ再生します。', 52, 200, 656, 16, MUTED, box, { lh: 1.6 });
  Cta('つづける', 52, 318, 320, back, box, 'ad-cta');
  globalThis.__muchi && (globalThis.__muchi.lastAd = sess.status);
}

// ---- time attack with ghosts (REQ-TA-*, friend ghosts first: REQ-UXS-074)
let taCache = null;
const taBestKey = (trackId) => 'muchi.proto.ta.' + trackId;
function taBest(trackId) { try { return JSON.parse(prefs.get(taBestKey(trackId), 'null')); } catch { return null; } }
async function TimeAttack(trackId = 'aoba_turf_1600', tab = '', selected = '') {
  await viewReady;
  const p = partner();
  const friends = prefs.get('muchi.proto.taFriends', '1') === '1';
  const key = trackId + ':' + friends + ':' + (taBest(trackId)?.timeMs ?? 0);
  if (taCache?.key !== key) {
    const { config, trackName, attemptsLeft } = await L.taConfig(p.id, trackId);
    const seeds = L.taGhostSeeds(trackId, friends);
    const best = taBest(trackId);
    const entries = seeds.map((s) => ({ id: s.id, name: s.name, horse: s.horse, kind: s.kind, config: s.config, whips: s.whips }));
    if (best) entries.push({ id: 'local', name: '自分のベスト', horse: p.name, kind: 'me', log: best.log });
    const times = JSON.parse(engine.TaGhosts(JSON.stringify(entries)));
    const list = entries.map((e) => ({ id: e.id, name: e.name, horse: e.horse, kind: e.kind, timeMs: times.find((t) => t.id === e.id).timeMs }));
    taCache = { key, config, trackName, attemptsLeft, list };
  }
  const best = taBest(trackId);
  const pk = JSON.parse(engine.PickGhosts(JSON.stringify(taCache.list), 'local', best?.timeMs ?? 0, tab, selected));
  currentScreen = () => TimeAttack(trackId, pk.tab, pk.selected);
  Clear('time-attack'); SetArt('Art/first-ride', false);
  TopBar(`タイムアタック　/　${taCache.trackName}`, 'ゴーストと並走します（相手には影響しません）', { wallet: false });
  const me = Glass('My best', 36, 134, 500, 676, undefined, .9);
  Kicker('自己ベスト　/　今シーズン', 36, 30, me);
  Txt(best ? fmtMs(best.timeMs) : '記録なし', 36, 100, 440, 64, best ? GOLD : DIM, me, { cls: 'num' });
  Txt(`相棒 ${p.name}　·　能力はTAの上限にそろえます`, 36, 196, 440, 16, WHITE, me, { weight: 500 });
  Txt(`今日の残り ${taCache.attemptsLeft}回（サーバーと同じ発行）`, 36, 228, 440, 16, WHITE, me, { weight: 500 });
  Hair(36, 290, 428, me);
  Kicker('デモ（レビュー用）', 36, 312, me, { rule: false, size: 14, color: SOFT });
  Ghost(friends ? 'フレンドのゴースト：あり' : 'フレンドのゴースト：なし', 36, 344, 428, 60, () => { prefs.set('muchi.proto.taFriends', friends ? '0' : '1'); TimeAttack(trackId); }, me, 'quiet').classList.add('ta-friends-toggle');
  Txt('相手の走りは全て端末のエンジンで計算した実際のタイムです。', 36, 420, 428, 13, SOFT, me);
  // picker: tabs フレンド / 上位 / 自分 (opens on フレンド; falls back to 上位 when no friend has run this course)
  const pp = Glass('Ghost picker', 556, 134, 1008, 676, undefined, .9); pp.dataset.tab = pk.tab; pp.dataset.fellback = String(pk.fellBack);
  pk.tabs.forEach((t, i) => {
    const b = Btn(`${t.label}（${t.count}）`, 32 + i * 180, 18, 168, 52, () => TimeAttack(trackId, t.kind, ''), 'stab tabtext ghosttab' + (t.kind === pk.tab ? ' on' : ''), pp);
    b.dataset.kind = t.kind;
  });
  if (pk.note) Txt(pk.note, 32, 86, 940, 16, GOLD, pp, { weight: 500 }).dataset.note = pk.fellBack ? 'fallback' : 'empty';
  pk.list.slice(0, 5).forEach((g, i) => {
    const row = Btn('', 32, 124 + i * 84, 944, 84, () => TimeAttack(trackId, pk.tab, g.id), 'row ghostrow' + (i === Math.min(4, pk.list.length - 1) ? ' last' : ''), pp);
    row.dataset.ghost = g.id; if (g.selected) row.classList.add('on');
    row.querySelector('span').remove();
    Txt((g.selected ? '▶ ' : '') + g.name, 8, 14, 520, 22, g.selected ? GOLD : WHITE, row, { weight: 700, nowrap: true });
    Txt(g.horse, 8, 48, 520, 14, MUTED, row, { nowrap: true });
    Txt(g.line, 440, 24, 496, 22, g.selected ? GOLD : WHITE, row, { weight: 700, align: 'right', cls: 'num', nowrap: true });
  });
  if (!pk.list.length && pk.tab === 'friends') Txt('フレンドを追加すると、ここにフレンドのベストが並びます。', 32, 140, 900, 18, DIM, pp);
  const sel = taCache.list.find((x) => x.id === pk.selected);
  Cta(sel ? `${sel.name}と走る` : 'ひとりで走る', 32, 576, 560, () => StartTimeAttack(trackId, sel?.id ?? ''), pp, 'gold').classList.add('ta-start');
  Ghost('ホーム', 776, 582, 200, 60, Home, pp, 'quiet');
}
const fmtMs = (ms) => { const t = Math.floor(ms / 100); return `${Math.floor(t / 600)}:${String(Math.floor(t / 10) % 60).padStart(2, '0')}.${t % 10}`; };
async function StartTimeAttack(trackId, ghostId) {
  await viewReady;
  raceInfo = JSON.parse(engine.StartTimeAttack(JSON.stringify(taCache.config), ghostId));
  raceCtx = { tutorial: false, ta: true, trackId, trackName: taCache.trackName, config: taCache.config, ghost: raceInfo.ghosts[0] ?? null };
  view.useRig = true; view.start(raceInfo, equippedPartner()); view.setGhosts(raceInfo.ghosts.length, equippedPartner());
  BuildRaceScreen();
  if (raceCtx.ghost) hud.ghost = Txt('', 545, 122, 510, 17, '#cfe8ff', undefined, { align: 'center', cls: 'tshadow', weight: 500 });
}
function TaResult(f) {
  const r = f.result, ta = f.ta, best = taBest(raceCtx.trackId);
  const newBest = ta.timeMs >= 0 && (!best || ta.timeMs < best.timeMs);
  if (newBest) { prefs.set(taBestKey(raceCtx.trackId), JSON.stringify({ timeMs: ta.timeMs, log: ta.log })); taCache = null; }
  const ghost = raceCtx.ghost, gt = ta.ghostTimes[0];
  currentScreen = () => TaResult(f);
  Clear('ta-result'); SetArt('Art/race-result');
  const p = ResultPanel(`タイムアタック　/　${raceCtx.trackName}`);
  Txt(r.time, 40, 118, 560, 96, newBest ? GOLD : WHITE, p, { cls: 'num', lh: 1.2 }).dataset.taTime = String(ta.timeMs);
  Txt(newBest ? '自己ベスト更新！' : best ? `自己ベスト ${fmtMs(best.timeMs)}` : '完走', 44, 248, 520, 30, newBest ? GOLD : WHITE, p);
  Hair(44, 320, 478, p);
  if (ghost && gt >= 0) {
    const d = (gt - ta.timeMs) / 1000;
    Kicker('ゴースト', 44, 346, p, { rule: false, size: 15 });
    Txt(`${ghost.name}（${fmtMs(gt)}）に ${Math.abs(d).toFixed(1)}秒差で${d > 0 ? '勝ち' : d < 0 ? '負け' : '同着'}`, 44, 372, 520, 21, d > 0 ? OK : WHITE, p, { weight: 700 }).dataset.vsGhost = d > 0 ? 'win' : 'lose';
  }
  Txt(r.line ? '一言：' + r.line : '', 44, 430, 520, 18, MUTED, p, { weight: 500 });
  Txt('記録はサーバーが同じエンジンで再計算して確定します（このプロトタイプでは端末に保存）。', 44, 520, 500, 14, SOFT, p, { lh: 1.6 });
  Cta('もう一度', 44, 640, 478, () => TimeAttack(raceCtx.trackId), p);
  TextLink('ホーム', 44, 734, 90, Home, p);
  Ghost('リプレイを共有', 1286, 800, 274, 60, () => ShareCard(currentScreen));
  EnToggle();
}

