      Txt(`${STYLE_JA[h.style] ?? ''}　${surfaceJa(h.surface)} ${fmt(h.distMinM)}〜${fmt(h.distMaxM)}m`, 380, yy, 232, 14, MUTED, s, { align: 'right', nowrap: true });
      Hair(48, yy + 34, 564, s);
